import re
from typing import Protocol

from app.core.errors import UserFacingError

# Keys are generated by the upload service (uuid4 hex + allowed extension), never from user
# input. Checking the shape anyway means a bad key can't reach the filesystem or bucket.
_STORAGE_KEY = re.compile(r"^[0-9a-f]{32}\.(pdf|docx|txt|md)$")


class StoredFileMissingError(UserFacingError):
    def __init__(self) -> None:
        super().__init__("The uploaded file could not be found in storage. Upload it again.")


class InvalidStorageKeyError(ValueError):
    pass


def validate_key(key: str) -> str:
    if not _STORAGE_KEY.fullmatch(key):
        raise InvalidStorageKeyError("Invalid storage key")
    return key


class Storage(Protocol):
    """Where uploaded files live. Local disk in development, an S3-compatible bucket in deploys."""

    async def save(self, key: str, data: bytes) -> None: ...

    async def read(self, key: str) -> bytes: ...

    async def delete(self, key: str) -> None: ...
